// Blueprint Edge Function boundary (B9).
// Authenticates and authorises the caller, prepares a bounded evidence pack, then runs the retry-safe
// A/B/C generation lifecycle with cache, quota reservation, backend verification and atomic persistence.
import { TEAM_SIZE, BUDGET_BAND, PREFERRED_STACK, BUSINESS_MODEL_HINT, TARGET_REGION, OPPORTUNITY_VERDICT } from '../_shared/blueprint/constants.ts';
import { buildEvidenceInputFromRows } from '../_shared/blueprint/evidence-source.ts';
import { prepareEvidencePack } from '../_shared/blueprint/evidence.ts';
import { checkBlueprintEntitlement, readDailyBlueprintLimit } from '../_shared/blueprint/access.ts';
import type { BlueprintRequestParams } from '../_shared/blueprint/contract.ts';
import { BlueprintResultStore } from '../_shared/blueprint/result-store.ts';
import { blueprintReservationKey } from '../_shared/blueprint/quota.ts';
import { runBlueprintGeneration } from '../_shared/blueprint/service.ts';
import { BLUEPRINT_CONFIG_VERSION } from '../_shared/blueprint/runtime.ts';
import { BLUEPRINT_DEFAULT_MODEL, blueprintProviderConfigProblem, BlueprintProviderError } from '../_shared/blueprint/provider.ts';
import { SupabaseStore } from '../_shared/collector/store.ts';

declare const Deno: { env: { get(name: string): string | undefined }; serve(handler: (request: Request) => Response | Promise<Response>): void };

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const UUID_LIST_BATCH = 100;
const PAGE_SIZE = 1000;

type JsonRecord = Record<string, unknown>;
type Params = {
  team_size: string;
  budget_band: string;
  preferred_stack: string;
  business_model_hint: string;
  target_region: string;
};

const cors = (req: Request): Record<string, string> => ({
  'access-control-allow-origin': '*',
  'access-control-allow-methods': 'POST, OPTIONS',
  'access-control-allow-headers': req.headers.get('access-control-request-headers') || 'authorization, apikey, content-type, x-client-info',
  'access-control-max-age': '86400',
});
const reply = (req: Request, body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors(req), 'content-type': 'application/json' } });
const deny = (req: Request, error: string, status: number) => reply(req, { error }, status);

function isObject(value: unknown): value is JsonRecord {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
function isOneOf(value: unknown, values: readonly string[]): value is string {
  return typeof value === 'string' && (values as readonly string[]).includes(value);
}
function parseRequest(value: unknown): { clusterId: string; requestKey: string; params: Params } | null {
  if (!isObject(value) || !isObject(value.params)) return null;
  const p = value.params;
  if (typeof value.cluster_id !== 'string' || !UUID.test(value.cluster_id)) return null;
  if (typeof value.request_key !== 'string' || value.request_key.length < 8 || value.request_key.length > 128) return null;
  if (!isOneOf(p.team_size, TEAM_SIZE) || !isOneOf(p.budget_band, BUDGET_BAND)
    || !isOneOf(p.preferred_stack, PREFERRED_STACK) || !isOneOf(p.business_model_hint, BUSINESS_MODEL_HINT)
    || !isOneOf(p.target_region, TARGET_REGION)) return null;
  return {
    clusterId: value.cluster_id,
    requestKey: value.request_key,
    params: {
      team_size: p.team_size,
      budget_band: p.budget_band,
      preferred_stack: p.preferred_stack,
      business_model_hint: p.business_model_hint,
      target_region: p.target_region,
    },
  };
}

function config() {
  const url = Deno.env.get('SUPABASE_URL');
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || Deno.env.get('SUPABASE_SERVICE_KEY');
  const anonKey = Deno.env.get('SUPABASE_ANON_KEY') || Deno.env.get('SUPABASE_PUBLISHABLE_KEY');
  return url && serviceKey && anonKey ? { url: url.replace(/\/$/, ''), serviceKey, anonKey } : null;
}

async function authUser(url: string, anonKey: string, authorization: string): Promise<{ id: string } | null> {
  const response = await fetch(url + '/auth/v1/user', { headers: { apikey: anonKey, authorization } });
  if (!response.ok) return null;
  const user: unknown = await response.json();
  return isObject(user) && typeof user.id === 'string' && UUID.test(user.id) ? { id: user.id } : null;
}

function quotaRpc(url: string, serviceKey: string) {
  return {
    async rpc<T>(name: string, args: Record<string, unknown>): Promise<T> {
      const response = await fetch(url.replace(/\/$/, '') + '/rest/v1/rpc/' + name, {
        method: 'POST',
        headers: {
          apikey: serviceKey,
          authorization: 'Bearer ' + serviceKey,
          'content-type': 'application/json',
          accept: 'application/json',
        },
        body: JSON.stringify(args),
      });
      if (!response.ok) throw new Error('blueprint_quota_rpc_failed:' + response.status);
      return await response.json() as T;
    },
  };
}

function serviceHeaders(serviceKey: string) {
  return { apikey: serviceKey, authorization: 'Bearer ' + serviceKey, accept: 'application/json' };
}

async function restGet<T>(url: string, headers: Record<string, string>, range?: string): Promise<T> {
  const response = await fetch(url, { headers: { ...headers, ...(range ? { range } : {}) } });
  if (!response.ok) throw new Error('database_read_failed');
  return await response.json() as T;
}

async function loadClusterEvidence(url: string, serviceKey: string, clusterId: string) {
  const headers = serviceHeaders(serviceKey);
  const base = url + '/rest/v1/';
  const clusterQuery = new URLSearchParams({
    select: 'id,title,industry,unique_discussions,source_count,sources,recent_discussions,prior_discussions,growth_rate,severity_avg,wtp_signals,competitors,scores,confidence',
    id: 'eq.' + clusterId,
    limit: '2',
  });
  const clusters = await restGet<JsonRecord[]>(base + 'dr_clusters?' + clusterQuery, headers);
  if (clusters.length !== 1) return { ok: false as const, error: 'cluster_not_found' as const };

  const memberships: JsonRecord[] = [];
  for (let start = 0; ; start += PAGE_SIZE) {
    const q = new URLSearchParams({ select: 'cluster_id,record_id', cluster_id: 'eq.' + clusterId, order: 'record_id.asc', limit: String(PAGE_SIZE) });
    const page = await restGet<JsonRecord[]>(base + 'dr_cluster_members?' + q, headers, `${start}-${start + PAGE_SIZE - 1}`);
    memberships.push(...page);
    if (page.length < PAGE_SIZE) break;
    if (memberships.length >= 10_000) return { ok: false as const, error: 'cluster_too_large' as const };
  }

  const recordIds = memberships.map((m) => m.record_id).filter((id): id is string => typeof id === 'string');
  const records: JsonRecord[] = [];
  const signals: JsonRecord[] = [];
  for (let i = 0; i < recordIds.length; i += UUID_LIST_BATCH) {
    const ids = recordIds.slice(i, i + UUID_LIST_BATCH);
    const inList = 'in.(' + ids.join(',') + ')';
    const recordQuery = new URLSearchParams({
      select: 'id,source_id,discussion_key,kind,url,title,excerpt,published_at,engagement,license,attribution,content_hash',
      id: inList,
      order: 'id.asc',
      limit: String(UUID_LIST_BATCH),
    });
    const signalQuery = new URLSearchParams({
      select: 'record_id,is_problem,wtp_evidence,analysis_method',
      record_id: inList,
      order: 'record_id.asc',
      limit: String(UUID_LIST_BATCH),
    });
    const [recordRows, signalRows] = await Promise.all([
      restGet<JsonRecord[]>(base + 'dr_raw_records?' + recordQuery, headers),
      restGet<JsonRecord[]>(base + 'dr_problem_signals?' + signalQuery, headers),
    ]);
    records.push(...recordRows);
    signals.push(...signalRows);
  }
  return { ok: true as const, rows: { cluster: clusters[0], memberships, records, signals } };
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors(req) });
  if (req.method !== 'POST') return deny(req, 'method_not_allowed', 405);

  const cfg = config();
  if (!cfg) return deny(req, 'server_misconfigured', 503);
  const authorization = req.headers.get('authorization');
  if (!authorization || !/^Bearer\s+\S+$/i.test(authorization)) return deny(req, 'unauthorized', 401);

  const user = await authUser(cfg.url, cfg.anonKey, authorization).catch(() => null);
  if (!user) return deny(req, 'session_invalid', 401);

  let raw: unknown;
  try { raw = await req.json(); } catch { return deny(req, 'invalid_json', 400); }
  const input = parseRequest(raw);
  if (!input) return deny(req, 'invalid_request', 400);

  const subQuery = new URLSearchParams({
    select: 'plan,status,current_period_end',
    user_id: 'eq.' + user.id,
    limit: '2',
  });
  let subscriptions: JsonRecord[];
  try {
    subscriptions = await restGet<JsonRecord[]>(cfg.url + '/rest/v1/subscriptions?' + subQuery, serviceHeaders(cfg.serviceKey));
  } catch {
    return deny(req, 'subscription_check_unavailable', 503);
  }
  if (subscriptions.length > 1) return deny(req, 'subscription_record_ambiguous', 403);
  const sub = subscriptions[0];
  const entitlement = checkBlueprintEntitlement(
    sub && typeof sub.plan === 'string' && typeof sub.status === 'string'
      ? { plan: sub.plan, status: sub.status, current_period_end: typeof sub.current_period_end === 'string' ? sub.current_period_end : null }
      : null,
    Date.now(),
  );
  if (!entitlement.allowed) return deny(req, 'blueprint_requires_active_pro_or_business', 403);

  let loaded: Awaited<ReturnType<typeof loadClusterEvidence>>;
  try { loaded = await loadClusterEvidence(cfg.url, cfg.serviceKey, input.clusterId); }
  catch { return deny(req, 'research_read_failed', 503); }
  if (!loaded.ok) return deny(req, loaded.error, loaded.error === 'cluster_not_found' ? 404 : 422);

  const mapped = buildEvidenceInputFromRows(loaded.rows);
  if (!mapped.ok) return deny(req, 'research_evidence_invalid', 422);
  const prepared = prepareEvidencePack(mapped.input);
  if (!prepared.ok) return deny(req, 'research_evidence_invalid', 422);

  // Start with a conservative per-user allowance until an explicit quota is configured.
  const dailyLimit = readDailyBlueprintLimit(Deno.env.get('BLUEPRINT_DAILY_LIMIT') || '1') ?? 1;

  const apiKey = Deno.env.get('OPENROUTER_API_KEY') || '';
  // Reuse the existing OpenRouter model secret; allow a Blueprint-specific override.
  const model = Deno.env.get('BLUEPRINT_MODEL') || Deno.env.get('OPENROUTER_MODEL') || BLUEPRINT_DEFAULT_MODEL;
  const timeoutRaw = Deno.env.get('BLUEPRINT_PASS_TIMEOUT_MS') || '90000';
  const timeoutMs = /^\d+$/.test(timeoutRaw) ? Number(timeoutRaw) : NaN;
  const provider = { apiKey, model, timeoutMs };
  if (blueprintProviderConfigProblem(provider) !== null) return deny(req, 'blueprint_provider_not_configured', 503);

  const requestParams = input.params as BlueprintRequestParams;
  let requestKeyHash: string;
  try {
    requestKeyHash = await blueprintReservationKey(user.id, input.requestKey, input.clusterId, requestParams);
  } catch {
    return deny(req, 'request_identity_invalid', 400);
  }

  try {
    const resultStore = new BlueprintResultStore({ supabaseUrl: cfg.url, serviceRoleKey: cfg.serviceKey });
    const cacheStore = new SupabaseStore(cfg.url, cfg.serviceKey);
    const result = await runBlueprintGeneration({
      identity: {
        userId: user.id,
        clusterId: input.clusterId,
        requestKeyHash,
        requestParams: { ...requestParams },
        model,
        configVersion: BLUEPRINT_CONFIG_VERSION,
      },
      dailyLimit,
      request: requestParams,
      evidence: prepared.value,
      allowedVerdicts: [...OPPORTUNITY_VERDICT],
      resultStore,
      quotaRpc: quotaRpc(cfg.url, cfg.serviceKey),
      cacheStore,
      provider,
    });

    if (result.state === 'completed' || result.state === 'completed_now') {
      return reply(req, {
        status: 'completed',
        reused: result.reused,
        result: result.result,
      });
    }
    if (result.state === 'limit_reached') return deny(req, 'blueprint_daily_limit_reached', 429);
    if (result.state === 'integrity_error') return deny(req, 'blueprint_integrity_error', 500);
    if (result.state === 'finalization_deferred') {
      return reply(req, { status: 'finalization_deferred', retryable: false }, 422);
    }

    const step = result.step;
    if (step.state === 'pass_completed') {
      return reply(req, {
        status: 'in_progress',
        completed_pass: step.completed,
        next_pass: step.next,
        retry_after_seconds: 2,
        evidence: prepared.value.summary,
        sufficiency: prepared.value.sufficiency.level,
      }, 202);
    }
    if (step.state === 'busy' || step.state === 'cooldown' || step.state === 'deferred') {
      return reply(req, {
        status: step.state,
        pass: step.pass,
        ...(step.reason ? { reason: step.reason } : {}),
        retry_after_seconds: step.state === 'busy' ? 3 : step.state === 'cooldown' ? 15 : 30,
      }, step.state === 'deferred' ? 503 : 202);
    }
    return deny(req, 'blueprint_unexpected_state', 500);
  } catch (error) {
    if (error instanceof BlueprintProviderError) {
      const status = error.code === 'rate_limited' ? 429
        : error.code === 'timeout' || error.code === 'network' || error.code === 'provider_unavailable' ? 503 : 502;
      return reply(req, { error: 'blueprint_provider_' + error.code, retryable: status === 429 || status === 503 }, status);
    }
    // Keep request text, source excerpts, provider bodies and credentials out of HTTP errors.
    return deny(req, 'blueprint_generation_unavailable', 503);
  }
});

// ProductBlueprint v1 - the single source of truth for every enum, identifier pattern, count and cap.
// Written from docs/blueprint-engine/product-blueprint-v1.md (section numbers below refer to it unless another document is named).
// The TypeScript types (contract.ts) and the validator (validate*.ts) are both derived from this module, so they cannot drift.
//
// Two kinds of numbers live here and are kept apart on purpose:
//  - DOCUMENTED limits: taken from the approved documents. They are authoritative.
//  - SAFEGUARDS: where the documents are silent, a conservative, explicit limit chosen in Phase A2. Each is listed in SAFEGUARDS with
//    the reason. They bound resources or reject content that cannot be meaningful; they do not change what the contract means.
//
// Runtime-agnostic (no Node or Deno specific API), like the rest of the shared code.

export const BLUEPRINT_SCHEMA_VERSION = 'product-blueprint.v1' as const;

/** Evidence contract section 6: the only valid market-sizing statement in v1. */
export const NOT_ESTIMATED_TEXT = 'Not estimated — insufficient market-sizing evidence';

/** Reliability document section 9.4: hard cap on a stored result, in bytes of UTF-8 JSON. Also applied to model output (a stricter bound is implied by the caps). */
export const BLUEPRINT_MAX_RESULT_BYTES = 262_144;

// ---------------------------------------------------------------------------------------------------------------------------------
// Identifier patterns (section 3.1). The regular expression is part of the contract.
// ---------------------------------------------------------------------------------------------------------------------------------

export const ID_PATTERNS = {
  evidence: /^[EM]\d{2}$/,
  persona: /^P\d$/,
  feature: /^F\d{1,2}$/,
  journey: /^J\d$/,
  workflow: /^W\d$/,
  component: /^C\d{1,2}$/,
  decision: /^D\d{1,2}$/,
  task: /^T\d{2}$/,
  phase: /^PH\d$/,
  criterion: /^AC\d{2}$/,
  experiment: /^X\d$/,
  risk: /^R\d{1,2}$/,
  assumption: /^A\d{1,2}$/,
  unknown: /^U\d{1,2}$/,
  gap: /^G\d$/,
  signal: /^S\d$/,
  pricing: /^H\d$/,
  goToMarketStep: /^GT\d$/,
} as const;

/** `validation_experiments[*].tests` holds assumption (A#) or unknown (U#) ids (section 3.7). */
export const EXPERIMENT_TARGET_PATTERN = /^(?:A\d{1,2}|U\d{1,2})$/;

/** Evidence contract section 3.1: the backend issues E01-E24 and M01-M16 only. An id outside these ranges can never have been supplied. */
export const EVIDENCE_EXCERPT_MAX_ID = 24;
export const EVIDENCE_METRIC_MAX_ID = 16;

/** Identifier shape for names the contract says are snake_case (table, column, workflow state). */
export const SNAKE_CASE_PATTERN = /^[a-z][a-z0-9_]*$/;

// ---------------------------------------------------------------------------------------------------------------------------------
// Enumerations. `as const` arrays so the types below are derived from the same values the validator checks.
// ---------------------------------------------------------------------------------------------------------------------------------

export const LEVEL3 = ['low', 'medium', 'high'] as const;
export const BASIS = ['verified_evidence', 'ai_recommendation', 'hypothesis', 'unknown'] as const;
export const OPPORTUNITY_VERDICT = ['pursue_mvp', 'validate_first', 'insufficient_evidence', 'not_recommended'] as const;
export const ALTERNATIVE_KIND = ['named_in_evidence', 'suggested_category'] as const;
export const SIGNAL_STRENGTH = ['weak', 'moderate', 'strong'] as const;
export const WTP_STATUS = ['evidenced', 'not_evidenced', 'unknown'] as const;
export const EVIDENCE_SUFFICIENCY = ['insufficient', 'limited', 'adequate'] as const;
export const PERSONA_PRIORITY = ['primary', 'secondary'] as const;
export const BUYING_ROLE = ['decision_maker', 'budget_holder', 'end_user', 'influencer', 'unknown'] as const;
export const PRODUCT_TYPE = ['web_app', 'mobile_app', 'api_service', 'browser_extension', 'integration', 'internal_tool', 'data_product', 'other'] as const;
export const COMPLEXITY = ['S', 'M', 'L'] as const;
export const FEATURE_PRIORITY = ['must', 'should'] as const;
export const STEP_ACTOR = ['user', 'system', 'admin', 'external_service'] as const;
export const ARCHITECTURE_STYLE = ['monolith', 'modular_monolith', 'serverless', 'client_heavy_with_baas', 'service_oriented'] as const;
export const TECH_AREA = ['frontend', 'backend', 'database', 'auth', 'hosting', 'integration', 'ai', 'observability', 'payments', 'other'] as const;
export const REVERSIBILITY = ['easy', 'moderate', 'hard'] as const;
export const INTEGRATION_DIRECTION = ['inbound', 'outbound', 'both'] as const;
export const NFR_CATEGORY = ['performance', 'security', 'privacy', 'availability', 'cost', 'compliance', 'scalability', 'observability', 'accessibility'] as const;
export const DB_ENGINE = ['postgresql'] as const;
export const TENANCY_MODEL = ['single_tenant', 'user_owned_rows', 'organisation_scoped', 'public_read_only'] as const;
export const REFERENTIAL_ACTION = ['cascade', 'restrict', 'set null', 'no action'] as const;
export const INDEX_METHOD = ['btree', 'gin', 'gist', 'hash', 'brin'] as const;
export const RLS_OPERATION = ['select', 'insert', 'update', 'delete', 'all'] as const;
export const RLS_ROLE = ['anon', 'authenticated', 'service_role'] as const;
export const EXPECTED_VOLUME = ['tiny', 'small', 'medium', 'large'] as const;
export const TASK_TYPE = ['backend', 'frontend', 'database', 'infrastructure', 'security', 'integration', 'testing', 'documentation'] as const;
export const TASK_SIZE = ['XS', 'S', 'M', 'L'] as const;
export const TEST_LEVEL = ['unit', 'integration', 'end_to_end', 'manual', 'performance', 'security'] as const;
export const EXPERIMENT_METHOD = ['customer_interview', 'landing_page_test', 'prototype_test', 'concierge_manual_service', 'survey', 'data_analysis'] as const;
export const PRICING_MODEL = ['subscription', 'usage_based', 'one_time', 'freemium', 'marketplace_fee', 'services_plus_software', 'undecided'] as const;
export const MARKET_SIZING_STATUS = ['not_estimated', 'hypothesis'] as const;
export const RISK_CATEGORY = ['market', 'technical', 'legal_compliance', 'operational', 'financial', 'data_quality', 'security_privacy', 'dependency'] as const;

/** Closed list of non-parameterised column types (section 3.6). Parameterised types are validated by PG_TYPE_PATTERNS. */
export const PG_SIMPLE_TYPES = [
  'uuid', 'text', 'boolean', 'smallint', 'integer', 'bigint', 'real', 'double precision',
  'date', 'time', 'timestamptz', 'jsonb', 'bytea', 'inet',
  'uuid[]', 'text[]', 'integer[]', 'bigint[]',
] as const;

// Backend-owned (section 3.9).
export const TEAM_SIZE = ['solo', 'small_team', 'larger_team'] as const;
export const BUDGET_BAND = ['bootstrap', 'small', 'funded'] as const;
export const PREFERRED_STACK = ['unspecified', 'typescript_postgres', 'python_postgres', 'low_code'] as const;
export const BUSINESS_MODEL_HINT = ['unspecified', 'b2b_saas', 'b2c_subscription', 'marketplace', 'api_usage_based'] as const;
export const TARGET_REGION = ['unspecified', 'global', 'north_america', 'europe', 'africa', 'asia_pacific', 'latin_america', 'middle_east'] as const;
export const PASS_NAME = ['A', 'B', 'C', 'single'] as const;
export const GENERATION_MODE = ['single_pass', 'sectioned'] as const;
export const METRIC_CLASS = ['measured', 'derived', 'ai_estimate', 'insufficient_data'] as const;
export const METRIC_NAME = [
  'unique_discussions', 'source_count', 'sources', 'recent_discussions', 'prior_discussions',
  'growth_rate_pct', 'wtp_signal_count', 'severity_avg', 'cluster_confidence', 'competitor_mentions', 'score_component',
] as const;
export const ANALYSIS_METHOD = ['llm', 'heuristic'] as const;
export const VERIFICATION_CHECK_NAME = [
  'json_parse', 'schema_shape', 'required_fields', 'enums', 'size_caps', 'identifier_integrity',
  'evidence_ref_resolution', 'basis_rules', 'name_and_number_grounding', 'willingness_to_pay_rule',
  'commercial_rules', 'no_executable_sql', 'no_urls',
] as const;
export const REPAIR_ACTION = ['downgraded_basis', 'dropped_ref', 'truncated_text', 'truncated_list', 'removed_unknown_key', 'replaced_with_canonical', 'reclassified'] as const;
export const VERIFICATION_STATUS = ['verified', 'verified_with_repairs'] as const;

/**
 * Phase A2 is rejection-only (no repair behaviour exists), so the only status a stored blueprint may carry is 'verified' and `repairs` must be
 * empty. This is a Phase A2 POLICY that narrows the documented type, which still lists 'verified_with_repairs' (product-blueprint-v1.md section 3.9).
 */
export const ACCEPTED_VERIFICATION_STATUS = 'verified' as const;

/**
 * Evidence contract section 5.1: "Each step names the VerificationCheckName it records". The nine steps record these 13 names, none of them is
 * conditional, and a rejected output is never stored, so a stored blueprint must carry every one exactly once with passed: true.
 * The validator checks the stored RECORD. It does not run the checks and cannot confirm that the backend ran them (grounding needs the evidence pack).
 */
export const REQUIRED_VERIFICATION_CHECKS: readonly (typeof VERIFICATION_CHECK_NAME)[number][] = VERIFICATION_CHECK_NAME;

/**
 * `meta.disclaimers` is "fixed backend text" (product-blueprint-v1.md section 3.9). The wording is given in the section 7 worked example, and
 * section 8 states the estimate label as the EXACT text. Arbitrary text is not accepted as backend-owned metadata: every entry must be one of these.
 */
export const ESTIMATE_DISCLAIMER = 'AI-generated estimate — not a delivery commitment';
export const FIXED_DISCLAIMERS: readonly string[] = [
  'AI-generated design proposal. Items marked hypothesis or ai_recommendation are not validated facts.',
  'Evidence excerpts are third-party content shown with source, licence and attribution.',
  ESTIMATE_DISCLAIMER,
];

/**
 * Evidence contract section 3.2: fixed metric catalogue. M01..M10 each have one name; M11..M16 are the six score components.
 * Index 0 is M01.
 */
export const METRIC_CATALOGUE_NAMES = [
  'unique_discussions', 'source_count', 'growth_rate_pct', 'wtp_signal_count', 'cluster_confidence',
  'sources', 'recent_discussions', 'prior_discussions', 'severity_avg', 'competitor_mentions',
  'score_component', 'score_component', 'score_component', 'score_component', 'score_component', 'score_component',
] as const;

/** Top-level keys the model writes (section 3.8). `schema_version` is the contract marker. */
export const MODEL_OUTPUT_KEYS = [
  'schema_version', 'opportunity', 'market_evidence', 'personas', 'product', 'mvp', 'journeys', 'workflows',
  'architecture', 'database', 'implementation', 'testing', 'commercial', 'risks',
] as const;

/** Keys only the backend may write (section 3.9; reliability document section 4.2, tier T1). */
export const BACKEND_OWNED_KEYS = ['meta', 'evidence_index', 'verification'] as const;

// ---------------------------------------------------------------------------------------------------------------------------------
// Counts and caps. DOCUMENTED unless the name or comment says SAFEGUARD.
// ---------------------------------------------------------------------------------------------------------------------------------

export interface Range { readonly min: number; readonly max: number }
const range = (min: number, max: number): Range => ({ min, max });

/** List sizes (section 3 and the section 5 summary table). */
export const COUNT = {
  // opportunity / market evidence
  alternatives: range(0, 6), thesis: range(1, 3), counterThesis: range(1, 3),
  demandSignals: range(1, 6), evidenceGaps: range(1, 6),
  // personas, product, MVP
  personas: range(1, 3), personaGoals: range(1, 4), personaFrustrations: range(1, 4),
